1	import {
2	  createContext,
3	  useCallback,
4	  useContext,
5	  useEffect,
6	  useMemo,
7	  useState,
8	  type AnchorHTMLAttributes,
9	  type MouseEvent,
10	  type ReactNode,
11	} from "react";
12	
13	type RouterValue = {
14	  path: string;
15	  navigate: (to: string) => void;
16	};
17	
18	const RouterContext = createContext<RouterValue>({ path: "/", navigate: () => {} });
19	
20	/**
21	 * Map a raw location pathname to an app route. The exported bundle may be
22	 * opened straight from the filesystem, where the pathname is a real file path
23	 * such as ".../output/index.html" or ".../output/_404.html".
24	 */
25	function normalize(path: string) {
26	  if (!path) return "/";
27	  if (path.endsWith("/_404.html")) return "/_404.html";
28	  if (path.endsWith("/index.html")) return "/";
29	  if (path.endsWith(".html")) return path.slice(path.lastIndexOf("/"));
30	  if (path.length > 1 && path.endsWith("/")) return path.slice(0, -1);
31	  return path;
32	}
33	
34	/** Separate an href into pathname + hash so in-page anchors survive routing. */
35	function splitHref(href: string) {
36	  const hashAt = href.indexOf("#");
37	  if (hashAt === -1) return { pathname: href, hash: "" };
38	  return { pathname: href.slice(0, hashAt), hash: href.slice(hashAt) };
39	}
40	
41	export function RouterProvider({ children }: { children: ReactNode }) {
42	  const [path, setPath] = useState(() => normalize(window.location.pathname));
43	
44	  useEffect(() => {
45	    const onPop = () => setPath(normalize(window.location.pathname));
46	    window.addEventListener("popstate", onPop);
47	    return () => window.removeEventListener("popstate", onPop);
48	  }, []);
49	
50	  const navigate = useCallback((to: string) => {
51	    const { pathname, hash } = splitHref(to);
52	    const target = normalize(pathname || window.location.pathname);
53	    const samePath = target === normalize(window.location.pathname);
54	
55	    if (samePath) {
56	      if (hash) document.getElementById(hash.slice(1))?.scrollIntoView({ behavior: "smooth" });
57	      return;
58	    }
59	
60	    try {
61	      window.history.pushState({}, "", target + hash);
62	    } catch {
63	      // e.g. opaque file:// origins where the History API is restricted.
64	    }
65	    setPath(target);
66	    if (hash) {
67	      window.requestAnimationFrame(() => {
68	        document.getElementById(hash.slice(1))?.scrollIntoView({ behavior: "smooth" });
69	      });
70	    } else {
71	      window.scrollTo(0, 0);
72	    }
73	  }, []);
74	
75	  const value = useMemo(() => ({ path, navigate }), [path, navigate]);
76	  return <RouterContext.Provider value={value}>{children}</RouterContext.Provider>;
77	}
78	
79	export function useRouter() {
80	  return useContext(RouterContext);
81	}
82	
83	/** hrefs the browser can resolve on its own: mail, phone, and bare anchors. */
84	function isBrowserHandled(href: string) {
85	  return (
86	    href.startsWith("#") ||
87	    href.startsWith("tel:") ||
88	    href.startsWith("mailto:") ||
89	    href.startsWith("javascript:")
90	  );
91	}
92	
93	type LinkProps = AnchorHTMLAttributes<HTMLAnchorElement> & {
94	  /** Destination path such as "/about/" or "/schools-colleges/". */
95	  to: string;
96	};
97	
98	/**
99	 * Client-side anchor. Root-relative destinations route through the in-app
100	 * router; protocol links and bare anchors fall through to the browser.
101	 */
102	export function Link({ to, children, onClick, ...rest }: LinkProps) {
103	  const { navigate } = useRouter();
104	
105	  if (isBrowserHandled(to)) {
106	    return (
107	      <a href={to} {...rest} onClick={onClick}>
108	        {children}
109	      </a>
110	    );
111	  }
112	
113	  const internal = to.startsWith("/");
114	  const href = internal ? to : "#";
115	
116	  const handleClick = (event: MouseEvent<HTMLAnchorElement>) => {
117	    onClick?.(event);
118	    if (!internal) {
119	      event.preventDefault();
120	      return;
121	    }
122	    if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey || event.button !== 0) {
123	      return;
124	    }
125	    event.preventDefault();
126	    navigate(to);
127	  };
128	
129	  return (
130	    <a href={href} {...rest} onClick={handleClick}>
131	      {children}
132	    </a>
133	  );
134	}
